with a as(select * from public.authors where open_library_id=any(array['OL76437A','OL108070A']::text[])),w as(select * from public.works where open_library_id=any(array['OL1067314W','OL873100W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780547559254','9780553244137','9789044635867','9789041330215']::text[]) or open_library_edition_id=any(array['OL29598317M','OL7821857M','OL45300996M','OL12804329M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987117001 and 987117999),'editions',(select count(*) from public.editions where id between 987217001 and 987217999),'authors',(select count(*) from public.authors where id between 987317001 and 987317999))) as preflight;
